      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background: var(--bg); color: var(--text);
      line-height: 1.6; -webkit-font-smoothing: antialiased;
      letter-spacing: -0.01em; font-feature-settings: 'cv11', 'ss01';
      transition: background 0.3s, color 0.3s;
      scrollbar-gutter: stable;
    }
    h1,h2,h3,h4,h5,h6 { color: var(--text); letter-spacing: -0.03em; line-height: 1.08; text-wrap: balance; }
    h1 { font-weight: 750; }
    h2 { font-weight: 650; }
    body, p, li, td, th, span, label { font-weight: 400; }
    p,li,td,th,span,label { color: var(--text); }
    .text-secondary { color: var(--text-secondary); }

    .card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 10px; padding: 18px 18px;
      transition: box-shadow 0.2s ease;
    }
    .card:hover { box-shadow: 0 0 0 1px var(--border), 0 8px 16px rgba(0,0,0,0.08); }

    @keyframes fadeInUp { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
    .animate { animation: fadeInUp 0.6s ease-out both; }
    .animate.delay-1 { animation-delay: 0.1s; }
    .animate.delay-2 { animation-delay: 0.2s; }

    .reveal { opacity: 0; transform: translateY(24px); transition: opacity 0.6s ease, transform 0.6s ease; }
    .reveal.visible { opacity: 1; transform: translateY(0); }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; }
      .reveal { opacity: 1; transform: none; }
    }

    @media print {
      body { background: white !important; color: black !important; }
      .viz-menu, .reveal { display: revert; opacity: 1 !important; transform: none !important; }
      .card { break-inside: avoid; border: 1px solid #ddd; box-shadow: none; }
      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }
    }
    @page { margin: 1in; @bottom-center { content: "Page " counter(page); font-size: 9pt; color: #666; } }

    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 9999; }
    .viz-menu-toggle {
      width: 44px; height: 44px; border-radius: 12px;
      background: var(--surface); border: 1px solid var(--border);
      color: var(--text); cursor: pointer; display: flex;
      align-items: center; justify-content: center;
      backdrop-filter: blur(12px); transition: all 0.2s;
    }
    .viz-menu-toggle:hover { background: var(--surface-hover); }
    .viz-menu-dropdown {
      position: absolute; top: 52px; right: 0; min-width: 200px;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 8px;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all 0.2s; backdrop-filter: blur(16px);
    }
    .viz-menu-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .viz-menu-dropdown button {
      width: 100%; padding: 10px 14px; border: none; border-radius: 8px;
      background: transparent; color: var(--text); font-size: 14px;
      font-family: inherit; cursor: pointer; text-align: left;
      display: flex; align-items: center; gap: 10px; transition: background 0.15s;
    }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }

    .skip-to-content {
      position: absolute; top: -40px; left: 6px; background: var(--accent);
      color: white; padding: 8px 12px; text-decoration: none;
      border-radius: 4px; opacity: 0; pointer-events: none;
      transition: all 0.2s; z-index: 10000;
    }
    .skip-to-content:focus { top: 6px; opacity: 1; pointer-events: auto; }

    /* ===== Visualization layout (data-dense, publication-ready) ===== */
    .container { max-width: 1180px; margin: 0 auto; padding: 26px 18px 28px; }
    header.hero { display: grid; grid-template-columns: 1.25fr 0.75fr; gap: 14px; align-items: start; margin-bottom: 14px; }
    .kicker {
      display: inline-flex; align-items: center; gap: 8px;
      font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase;
      color: var(--text-secondary);
    }
    .kicker .dot { width: 8px; height: 8px; border-radius: 999px; background: var(--warning); box-shadow: 0 0 0 3px color-mix(in oklab, var(--warning), transparent 80%); }
    h1 { font-size: 28px; margin-top: 10px; }
    .subtitle { margin-top: 10px; font-size: 13px; color: var(--text-secondary); max-width: 68ch; }

    .legend-card { padding: 16px; }
    .legend-title { font-size: 13px; font-weight: 600; margin-bottom: 10px; }
    .legend-grid { display: grid; grid-template-columns: 1fr; gap: 10px; }
    .legend-item { display: grid; grid-template-columns: 14px 1fr; gap: 10px; align-items: start; }
    .swatch { width: 12px; height: 12px; border-radius: 3px; margin-top: 3px; }
    .legend-item .label { font-size: 12px; line-height: 1.35; }
    .legend-item .label b { font-weight: 650; }

    .chart-card { padding: 16px 16px 14px; }
    .chart-head { display: flex; justify-content: space-between; gap: 12px; align-items: baseline; margin-bottom: 10px; }
    .chart-head h2 { font-size: 16px; }
    .chart-head .meta { font-size: 12px; color: var(--text-secondary); }
    .chart-wrap { position: relative; height: 560px; }

    .footnotes { margin-top: 12px; font-size: 11.5px; color: var(--text-secondary); display: grid; gap: 6px; }
    .pill { display:inline-flex; align-items:center; gap:8px; padding:6px 10px; border-radius: 999px; background: color-mix(in oklab, var(--surface), transparent 0%); border: 1px solid var(--border); font-size: 12px; color: var(--text-secondary); }
    .pill strong { color: var(--text); font-weight: 650; }

    @media (max-width: 920px) {
      header.hero { grid-template-columns: 1fr; }
      .chart-wrap { height: 620px; }
    }
  </style>
</head>
<body>
  <a href="#main-content" class="skip-link" style="position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;" onfocus="this.style.cssText='position:fixed;left:16px;top:16px;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;'" onblur="this.style.cssText='position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;'">Skip to content</a>
  <main id="main-content">

  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>

  <a href="#main-content" class="skip-to-content">Skip to content</a>

  <main id="main-content" role="main">
    <section class="container">
      <header class="hero animate">
        <div>
          <div class="kicker"><span class="dot" aria-hidden="true"></span><span>Global water stress — 10‑country comparison</span></div>
          <h1>Water crisis hotspots emerge where multiple indicators converge (2023)</h1>
          <p class="subtitle">Each row is a country; each column is a stress indicator normalized within this 10‑country set. Darker shading means worse conditions. Arrows show whether mean precipitation moved up or down from the 1990s to the 2010s.</p>
          <div style="margin-top:12px; display:flex; flex-wrap:wrap; gap:8px">
            <span class="pill"><strong>Water balance</strong> supply ÷ demand (ratio)</span>
            <span class="pill"><strong>Groundwater</strong> extraction ÷ recharge (ratio)</span>
            <span class="pill"><strong>Freshwater</strong> m³/person/year</span>
            <span class="pill"><strong>Rainfall trend</strong> 1990s → 2010s (%)</span>
          </div>
        </div>
        <aside class="card legend-card animate delay-1">
          <div class="legend-title">How to read</div>
          <div class="legend-grid">
            <div class="legend-item">
              <span class="swatch" style="background: linear-gradient(180deg, rgba(244,63,94,0.95), rgba(244,63,94,0.25)); border:1px solid rgba(244,63,94,0.35)"></span>
              <div class="label"><b>More severe</b> (worse within this group) shown with stronger red shading.</div>
            </div>
            <div class="legend-item">
              <span class="swatch" style="background: linear-gradient(180deg, rgba(16,185,129,0.9), rgba(16,185,129,0.20)); border:1px solid rgba(16,185,129,0.35)"></span>
              <div class="label"><b>Less severe</b> shown with weaker shading.</div>
            </div>
            <div class="legend-item">
              <span class="swatch" style="background: var(--negative)"></span>
              <div class="label"><b>↓ precipitation</b> from 1990s to 2010s (trend overlay).</div>
            </div>
            <div class="legend-item">
              <span class="swatch" style="background: var(--positive)"></span>
              <div class="label"><b>↑ precipitation</b> from 1990s to 2010s.</div>
            </div>
          </div>
        </aside>
      </header>

      <section class="card chart-card" data-reveal>
        <div class="chart-head">
          <h2>Multi‑indicator heatmap (ordered by composite severity)</h2>
          <div class="meta">Units: ratios (dimensionless), m³/person/year, precipitation change (%)</div>
        </div>
        <div class="chart-wrap">
          <canvas id="heatmap" role="img" aria-label="Heatmap comparing 10 countries across water stress indicators"></canvas>
        </div>
        <div class="footnotes">
          <div>Normalization: each indicator is min–max scaled across the 10 countries; for supply÷demand and per‑capita freshwater, lower values map to higher severity.</div>
          <div>Source: `/app/benchmark/source_data.json` (2023 estimates; precipitation decadal means for 1990s/2000s/2010s).</div>
        </div>
      </section>
    </section>
  </main>

  </main>
  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    document.querySelectorAll('[data-reveal]').forEach(function(el){ el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el){ revealObserver.observe(el); });

    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
        var a = document.createElement('a'); a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return null; }
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var canvas = document.getElementById(canvasId);
          if (!canvas) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (canvas.chart) { canvas.chart.destroy(); delete canvas.chart; }
          canvas.setAttribute('role', 'img');
          if (!canvas.getAttribute('aria-label')) canvas.setAttribute('aria-label', 'Chart visualization');
          var ctx = canvas.getContext('2d');
          var chart = new Chart(ctx, config);
          canvas.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (err) {
          console.error('Chart init failed for ' + canvasId, err);
          return null;
        }
      }
    };

    var DATA = {
      countries: [
        'Saudi Arabia','Egypt','Pakistan','South Africa','India','Mexico','United States','Australia','Brazil','Canada'
      ],
      // source_data.json.water_supply_demand.data (2023)
      supplyDemandRatio: [0.31,0.48,0.65,0.91,0.72,1.08,1.82,1.55,4.35,6.12],
      // source_data.json.groundwater_extraction.data (2023)
      extractionRechargeRatio: [5.66,1.63,1.16,0.98,0.58,0.75,0.88,0.23,0.10,0.05],
      // source_data.json.per_capita_freshwater.data (2023)
      perCapitaM3: [84,570,934,830,1486,3656,8844,20180,27436,80620],
      // precipitation_trends: pct change 1990s -> 2010s
      precipPct1990to2010: [-20.4,-21.2,-10.4,-9.2,-3.8,-4.4,4.0,2.8,-2.3,4.7]
    };

    function minMaxScale(values) {
      var minV = Math.min.apply(null, values);
      var maxV = Math.max.apply(null, values);
      return values.map(function(v){ return (maxV === minV) ? 0 : (v - minV) / (maxV - minV); });
    }

    function clamp01(x) { return Math.max(0, Math.min(1, x)); }

    function lerp(a, b, t) { return a + (b - a) * t; }

    function rgba(r,g,b,a){ return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')'; }

    function severityColor(t, isDark) {
      // t: 0 (best) -> 1 (worst)
      // Publication-ready red ramp with neutral low end.
      var low = isDark ? [26, 28, 30] : [245, 245, 244];
      var mid = [245, 158, 11];
      var high = [244, 63, 94];
      var r,g,b;
      if (t < 0.55) {
        var tt = t / 0.55;
        r = Math.round(lerp(low[0], mid[0], tt));
        g = Math.round(lerp(low[1], mid[1], tt));
        b = Math.round(lerp(low[2], mid[2], tt));
      } else {
        var tt2 = (t - 0.55) / 0.45;
        r = Math.round(lerp(mid[0], high[0], tt2));
        g = Math.round(lerp(mid[1], high[1], tt2));
        b = Math.round(lerp(mid[2], high[2], tt2));
      }
      var a = isDark ? (0.22 + 0.55 * t) : (0.14 + 0.60 * t);
      return { fill: rgba(r,g,b,a), stroke: rgba(r,g,b, Math.min(1, a + 0.20)) };
    }

    function buildHeatmap() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }

      var isDark = document.documentElement.classList.contains('theme-dark');
      var textColor = isDark ? '#EDEDED' : '#0f172a';
      var subColor = isDark ? 'rgba(237,237,237,0.62)' : 'rgba(15,23,42,0.62)';
      var gridColor = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)';
      var borderSoft = isDark ? 'rgba(255,255,255,0.12)' : 'rgba(0,0,0,0.10)';

      // severity (worse = higher)
      var ratio = DATA.supplyDemandRatio;
      var gw = DATA.extractionRechargeRatio;
      var pc = DATA.perCapitaM3;

      var ratioScaled = minMaxScale(ratio).map(function(v){ return 1 - v; });
      var gwScaled = minMaxScale(gw);
      var pcScaled = minMaxScale(pc).map(function(v){ return 1 - v; });

      var metrics = [
        { key: 'ratio', label: 'Supply ÷ demand (ratio)', values: ratioScaled,
          raw: ratio, unit: 'ratio', invert: true,
          note: 'Below 1.0 → demand exceeds supply' },
        { key: 'gw', label: 'Extraction ÷ recharge (ratio)', values: gwScaled,
          raw: gw, unit: 'ratio', invert: false,
          note: 'Above 1.0 → groundwater overdraft' },
        { key: 'pc', label: 'Freshwater per capita (m³/person/yr)', values: pcScaled,
          raw: pc, unit: 'm³/person/yr', invert: true,
          note: 'Below 1,000 often indicates scarcity' }
      ];

      // Heatmap cells: use scatter with rectangular points
      var points = [];
      for (var i = 0; i < DATA.countries.length; i++) {
        for (var j = 0; j < metrics.length; j++) {
          points.push({ x: j, y: i, v: metrics[j].values[i], raw: metrics[j].raw[i], unit: metrics[j].unit, key: metrics[j].key });
        }
      }

      // Trend overlay as separate dataset with directional arrow and percent label.
      var trendPoints = DATA.countries.map(function(c, i) {
        return { x: 2.9, y: i, pct: DATA.precipPct1990to2010[i] };
      });

      // Background row separators
      var rowLines = [];
      for (var r = 0; r <= DATA.countries.length; r++) rowLines.push({ y: r - 0.5 });

      var cfg = {
        type: 'scatter',
        data: {
          datasets: [
            {
              label: 'Indicator severity (normalized within group)',
              data: points,
              parsing: false,
              pointStyle: 'rectRounded',
              pointRadius: function(ctx) {
                var chart = ctx.chart;
                var area = chart.chartArea;
                if (!area) return 10;
                var rowH = (area.bottom - area.top) / DATA.countries.length;
                return Math.max(10, Math.min(22, rowH * 0.36));
              },
              pointHoverRadius: function(ctx) {
                var base = (typeof ctx === 'number') ? 14 : 14;
                return base;
              },
              pointRotation: 0,
              pointBackgroundColor: function(ctx) {
                var v = ctx.raw && typeof ctx.raw.v === 'number' ? clamp01(ctx.raw.v) : 0;
                return severityColor(v, isDark).fill;
              },
              pointBorderColor: function(ctx) {
                var v = ctx.raw && typeof ctx.raw.v === 'number' ? clamp01(ctx.raw.v) : 0;
                return severityColor(v, isDark).stroke;
              },
              pointBorderWidth: 1,
              pointHitRadius: 10
            },
            {
              label: 'Precipitation trend (1990s → 2010s)',
              data: trendPoints,
              parsing: false,
              pointRadius: 0,
              showLine: false,
              pointHitRadius: 0
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          layout: { padding: { top: 8, right: 20, bottom: 8, left: 8 } },
          plugins: {
            tooltip: {
              enabled: true,
              callbacks: {
                title: function(items) {
                  if (!items || !items.length) return '';
                  var it = items[0];
                  var y = it.raw && typeof it.raw.y === 'number' ? it.raw.y : null;
                  return (y === null) ? '' : DATA.countries[y];
                },
                label: function(ctx) {
                  var raw = ctx.raw;
                  if (!raw) return '';
                  if (typeof raw.v === 'number') {
                    var m = metrics[raw.x];
                    var note = m && m.note ? ' — ' + m.note : '';
                    var val = raw.raw;
                    var s = m.key === 'pc' ? Math.round(val).toLocaleString() : (Math.round(val * 100) / 100).toString();
                    if (m.key === 'ratio') s = (Math.round(val * 100) / 100).toFixed(2);
                    if (m.key === 'gw') s = (Math.round(val * 100) / 100).toFixed(2);
                    return m.label + ': ' + s + (m.key === 'pc' ? ' m³/person/yr' : '') + note;
                  }
                  if (typeof raw.pct === 'number') {
                    var dir = raw.pct < 0 ? 'Decreasing' : 'Increasing';
                    return 'Precipitation trend: ' + dir + ' (' + raw.pct.toFixed(1) + '%)';
                  }
                  return '';
                }
              }
            },
            legend: {
              display: true,
              position: 'bottom',
              labels: {
                color: subColor,
                usePointStyle: true,
                boxWidth: 10,
                boxHeight: 10,
                padding: 14
              }
            },
            title: {
              display: false
            }
          },
          scales: {
            x: {
              type: 'linear',
              min: -0.6,
              max: 3.25,
              grid: { color: gridColor },
              border: { color: borderSoft },
              ticks: {
                color: subColor,
                callback: function(value) {
                  // show labels at 0,1,2 only
                  if (value === 0) return 'Supply ÷ demand';
                  if (value === 1) return 'Extract ÷ recharge';
                  if (value === 2) return 'Per‑capita freshwater';
                  if (value === 3) return 'Precip trend';
                  return '';
                },
                stepSize: 1
              },
              title: {
                display: true,
                text: 'Indicators (severity shading normalized within this set)',
                color: subColor,
                font: { size: 12, weight: '600' }
              }
            },
            y: {
              type: 'linear',
              min: -0.6,
              max: DATA.countries.length - 0.4,
              grid: { display: false },
              border: { color: borderSoft },
              ticks: {
                color: textColor,
                callback: function(value) {
                  var idx = Math.round(value);
                  if (Math.abs(value - idx) > 0.001) return '';
                  return DATA.countries[idx] || '';
                }
              },
              title: {
                display: true,
                text: 'Countries (ranked by composite severity across indicators)',
                color: subColor,
                font: { size: 12, weight: '600' }
              }
            }
          }
        },
        plugins: [
          {
            id: 'heatmapRect',
            afterDatasetsDraw: function(chart) {
              var ctx = chart.ctx;
              var area = chart.chartArea;
              if (!area) return;
              // draw subtle row separators
              ctx.save();
              ctx.strokeStyle = gridColor;
              ctx.lineWidth = 1;
              for (var i = 0; i < DATA.countries.length + 1; i++) {
                var y = chart.scales.y.getPixelForValue(i - 0.5);
                ctx.beginPath();
                ctx.moveTo(area.left, y);
                ctx.lineTo(area.right, y);
                ctx.stroke();
              }
              // draw trend arrows and pct labels
              var xArrow = chart.scales.x.getPixelForValue(3.0);
              for (var r = 0; r < trendPoints.length; r++) {
                var yPx = chart.scales.y.getPixelForValue(r);
                var pct = DATA.precipPct1990to2010[r];
                var isDown = pct < 0;
                var col = isDown ? (isDark ? 'rgba(244,63,94,0.95)' : 'rgba(225,29,72,0.95)') : (isDark ? 'rgba(16,185,129,0.95)' : 'rgba(5,150,105,0.95)');
                ctx.fillStyle = col;
                ctx.strokeStyle = col;
                // arrow
                ctx.beginPath();
                var size = 10;
                if (isDown) {
                  ctx.moveTo(xArrow, yPx + size);
                  ctx.lineTo(xArrow, yPx - size);
                  ctx.lineTo(xArrow - 5, yPx - size + 6);
                  ctx.moveTo(xArrow, yPx - size);
                  ctx.lineTo(xArrow + 5, yPx - size + 6);
                } else {
                  ctx.moveTo(xArrow, yPx - size);
                  ctx.lineTo(xArrow, yPx + size);
                  ctx.lineTo(xArrow - 5, yPx + size - 6);
                  ctx.moveTo(xArrow, yPx + size);
                  ctx.lineTo(xArrow + 5, yPx + size - 6);
                }
                ctx.lineWidth = 2;
                ctx.stroke();

                // pct text
                ctx.font = '12px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
                ctx.textBaseline = 'middle';
                ctx.fillStyle = subColor;
                var txt = (pct >= 0 ? '+' : '') + pct.toFixed(1) + '%';
                ctx.fillText(txt, xArrow + 10, yPx);
              }
              ctx.restore();
            }
          },
          {
            id: 'rectPoints',
            beforeDatasetsDraw: function(chart) {
              // Replace default points with fixed-size rounded rect cells for dataset 0.
              var dsMeta = chart.getDatasetMeta(0);
              if (!dsMeta || !dsMeta.data) return;
              var area = chart.chartArea;
              if (!area) return;
              var colCount = 3;
              var rowCount = DATA.countries.length;
              var colW = (chart.scales.x.getPixelForValue(1) - chart.scales.x.getPixelForValue(0));
              var rowH = (chart.scales.y.getPixelForValue(1) - chart.scales.y.getPixelForValue(0));
              var cellW = Math.min(160, Math.max(92, colW * 0.86));
              var cellH = Math.min(44, Math.max(26, Math.abs(rowH) * 0.70));
              // store for tooltip hitboxes
              chart.$cellGeom = { cellW: cellW, cellH: cellH };
              var ctx = chart.ctx;
              ctx.save();
              // draw cells manually and hide the default elements
              for (var i = 0; i < dsMeta.data.length; i++) {
                var el = dsMeta.data[i];
                if (!el) continue;
                // hide default draw
                el.skip = true;
                var raw = chart.data.datasets[0].data[i];
                var px = chart.scales.x.getPixelForValue(raw.x);
                var py = chart.scales.y.getPixelForValue(raw.y);
                var v = clamp01(raw.v);
                var col = severityColor(v, isDark);
                var x = px - cellW/2;
                var y = py - cellH/2;
                var r = 8;
                ctx.fillStyle = col.fill;
                ctx.strokeStyle = col.stroke;
                ctx.lineWidth = 1;
                // rounded rect
                ctx.beginPath();
                ctx.moveTo(x+r, y);
                ctx.arcTo(x+cellW, y, x+cellW, y+cellH, r);
                ctx.arcTo(x+cellW, y+cellH, x, y+cellH, r);
                ctx.arcTo(x, y+cellH, x, y, r);
                ctx.arcTo(x, y, x+cellW, y, r);
                ctx.closePath();
                ctx.fill();
                ctx.stroke();

                // raw value label
                ctx.fillStyle = textColor;
                ctx.font = '12px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                var m = metrics[raw.x];
                var label = '';
                if (m.key === 'pc') {
                  label = Math.round(raw.raw).toLocaleString();
                } else {
                  label = (Math.round(raw.raw * 100) / 100).toFixed(2);
                }
                ctx.fillText(label, px, py);
              }
              ctx.restore();
            }
          }
        ]
      };

      ChartManager.safeInit('heatmap', cfg);
    }

    function onThemeChange() { buildHeatmap(); }
    window.addEventListener('load', function() { buildHeatmap(); });
  </script>
</body>
</html>
